svg.script:
//
const hotspotData = {
  default: {
    title: "Fêmur Proximal & Quadril",
    subtitle: "Caso Clínico: Dona Helena, 82 anos",
    text: "Idosa trazida ao pronto-socorro após queda da própria altura. Apresenta dor intensa na região inguinal direita, encurtamento e rotação externa do membro inferior afetado (posição de impotência funcional). A fratura de colo de fêmur é um elo crítico na cascata de fragilidade do idoso.",
    warning: "Mortalidade em 1 ano: ~20-30% por complicações secundárias à imobilização.",
    warningClass: "red"
  },
  colo: {
    title: "Colo do Fêmur",
    subtitle: "Fratura Intracapsular (Sítio Crítico)",
    text: "Fratura localizada na zona de transição de forças. A osteoporose causa perda de trabéculas ósseas no colo (triângulo de Ward), tornando-o altamente suscetível a fraturas sob traumas mínimos. Exige cirurgia para mobilização precoce.",
    warning: "Classificação de Garden: Grau III ou IV nas fraturas desviadas.",
    warningClass: "amber"
  },
  cabeca: {
    title: "Cabeça Femoral",
    subtitle: "Suprimento Arterial & Risco de Necrose",
    text: "A circulação da cabeça femoral é de tipo terminal e retrógrada, vinda das artérias retinaculares (ACFM). O desvio da fratura cisalha esses vasos, causando isquemia e necrose avascular da cabeça femoral.",
    warning: "ALERTA: Necrose Avascular ocorre em até 30% dos desvios.",
    warningClass: "red"
  },
  acetabulo: {
    title: "Acetábulo & Articulação",
    subtitle: "Articulação Coxofemoral",
    text: "Cavidade profunda da pelve que abriga a cabeça femoral. A cartilagem articular necessita de movimento e carga para nutrição. A imobilidade pós-fratura gera dor crônica e rigidez articular acelerada.",
    warning: "Articulação coxofemoral estável, sem luxação primária associada.",
    warningClass: "green"
  },
  trocanter: {
    title: "Grande Trocanter",
    subtitle: "Braço de Alavanca & Glúteo Médio",
    text: "Sítio de inserção dos glúteos médio e mínimo, responsáveis pela estabilização da pelve (sinal de Trendelenburg). O trauma direto lateral na queda atinge o trocanter maior, transferindo a energia ao colo femoral.",
    warning: "Força de tração muscular desvia o fragmento diafisário proximalmente.",
    warningClass: "amber"
  },
  diafise: {
    title: "Diáfise Femoral",
    subtitle: "Eixo Cortical de Carga",
    text: "Osso cortical extremamente denso que suporta a carga corporal. Permanece intacto na fratura do colo, mas serve de ancoragem para hastes de fixação ou hastes longas de artroplastia se houver má qualidade óssea.",
    warning: "Normal. Alinhamento axial comprometido pelo desvio no estado fraturado.",
    warningClass: "green"
  }
};

function wrapText(text, elementId, x, width, fontSize, lineHeight) {
  const el = document.getElementById(elementId);
  el.innerHTML = ''; // clear existing
  const words = text.split(' ');
  let line = '';
  let lineCount = 0;

  for (let i = 0; i < words.length; i++) {
    let testLine = line + words[i] + ' ';
    if (testLine.length * (fontSize * 0.53) > width && i > 0) {
      let tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      tspan.setAttribute('x', x);
      tspan.setAttribute('dy', lineCount === 0 ? '0' : lineHeight + 'px');
      tspan.textContent = line.trim();
      el.appendChild(tspan);
      line = words[i] + ' ';
      lineCount++;
    } else {
      line = testLine;
    }
  }
  let tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
  tspan.setAttribute('x', x);
  tspan.setAttribute('dy', lineCount === 0 ? '0' : lineHeight + 'px');
  tspan.textContent = line.trim();
  el.appendChild(tspan);
}

function updatePanel(id) {
  const data = hotspotData[id] || hotspotData['default'];

  document.getElementById('panel-title').textContent = data.title;
  document.getElementById('panel-subtitle').textContent = data.subtitle;

  // Wrap body text
  wrapText(data.text, 'panel-text', 20, 270, 13, 17);

  // Wrap warning text
  wrapText(data.warning, 'panel-warning-text', 12, 245, 11, 15);

  // Update warning box styling
  const warningBox = document.getElementById('panel-warning-box');
  const warningText = document.getElementById('panel-warning-text');

  warningBox.setAttribute('class', 'panel-warning-card ' + data.warningClass + '-bg');
  warningText.setAttribute('class', 'panel-warning-txt ' + data.warningClass + '-fg');

  // Highlight active hotspot
  const hotspots = ['colo', 'cabeca', 'acetabulo', 'trocanter', 'diafise'];
  hotspots.forEach(hId => {
    const el = document.getElementById('hotspot-' + hId);
    if (el) {
      if (hId === id) {
        el.classList.add('active');
      } else {
        el.classList.remove('active');
      }
    }
  });
}

function setFemurState(isFractured) {
  const root = document.getElementById('femur-svg-container');
  const btnIntact = document.getElementById('btn-state-intact');
  const btnFractured = document.getElementById('btn-state-fractured');
  const distalFragment = document.getElementById('femur-distal-fragment');

  if (isFractured) {
    root.classList.remove('femur-state-intact');
    root.classList.add('femur-state-fractured');

    btnFractured.classList.add('active');
    btnIntact.classList.remove('active');

    // Typical displacement: Shortening (upward displacement) and external rotation (left/outward shift)
    distalFragment.setAttribute('transform', 'translate(-12, -18) rotate(-4)');

    updatePanel('colo');
  } else {
    root.classList.remove('femur-state-fractured');
    root.classList.add('femur-state-intact');

    btnIntact.classList.add('active');
    btnFractured.classList.remove('active');

    distalFragment.setAttribute('transform', 'translate(0, 0) rotate(0)');

    updatePanel('default');
  }
}

// Initialize with default state
window.addEventListener('DOMContentLoaded', () => {
  updatePanel('default');
});
// Fallback if DOMContentLoaded already fired
if (document.readyState === 'complete' || document.readyState === 'interactive') {
  updatePanel('default');
}
//
